import{_ as e}from"./chunks/field-en.BujBbIY0.js";import{_ as a,o as r,c as o,a2 as n}from"./chunks/framework.DHtetOlu.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),s={name:"en/guide/index.md"};function i(d,t,l,h,c,m){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>MagFEM</strong> solves two-dimensional magnetic field problems with the finite element method, right in the browser. It is meant for inductors, transformers, actuators, contactors and, later, rotating machines. Problems can be <strong>planar</strong> (a cross-section with a depth) or <strong>axisymmetric</strong> (solids of revolution around the z axis).</p><ul><li><strong>No installation and no server.</strong> The numerical core (C++ and Eigen) is compiled to WebAssembly and runs in a Web Worker. Your project stays on your machine, as in draw.io.</li><li><strong>English and Portuguese</strong>, light and dark themes, and the <strong>Cite</strong> button at the top.</li><li><strong>Open source</strong> (MIT) on <a href="https://github.com/thalesmaoa/magfem" target="_blank" rel="noreferrer">GitHub</a>. Bugs and ideas: <a href="https://github.com/thalesmaoa/magfem/issues" target="_blank" rel="noreferrer">issues</a>.</li></ul><p>Open it at <a href="https://thalesmaia.com/tools/magfem-web/" target="_blank" rel="noreferrer">https://thalesmaia.com/tools/magfem-web/</a>. It works best in Chrome or Edge, which can save straight to the same file; in Firefox and Safari, saving becomes a download.</p><h2 id="the-workflow" tabindex="-1">The workflow <a class="header-anchor" href="#the-workflow" aria-label="Permalink to &quot;The workflow&quot;">​</a></h2><p>The tree on the left follows the order of the work, as in COMSOL:</p><ol><li><strong>Geometry</strong> — the parametric drawing (entities, constraints, dimensions and variables).</li><li><strong>Mesh</strong> — region materials, circuits, boundaries, element size and the mesh.</li><li><strong>Solver</strong> — the physics (magnetic field or circuit) and the analysis type.</li><li><strong>Results</strong> — field views, plots and tables, each one in a canvas tab.</li></ol><p><img src="'+e+'" alt="MagFEM with a solved field" class="shot"></p><h2 id="the-interface" tabindex="-1">The interface <a class="header-anchor" href="#the-interface" aria-label="Permalink to &quot;The interface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Contents</th></tr></thead><tbody><tr><td>Top bar</td><td>New, Open, Save, Save as, Import, Export, Cite, language (PT/EN) and theme</td></tr><tr><td>Toolbar</td><td>drawing, constraints, dimension and editing (trim, offset, mirror, patterns), move and group</td></tr><tr><td>Model tree</td><td>the four stages; each node&#39;s <code>+</code> creates items; double-click renames</td></tr><tr><td>Properties</td><td>below the tree: the properties of the selection</td></tr><tr><td>Canvas</td><td>the drawing and the result tabs (views, plots, tables, schematic)</td></tr><tr><td>Right drawer</td><td><strong>Problem and libraries</strong>: unit, planar/axisymmetric, depth, materials and boundaries</td></tr><tr><td>Console</td><td>every action shows up as an API command; typed commands work too</td></tr><tr><td>Status bar</td><td>coordinates, degrees of freedom, hints, <strong>Local script</strong>, Bug reports and the version</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Build the <a href="./first-model.html">first model</a>: an axisymmetric coil with a steel core, from the drawing to the inductance.</li><li>Learn how to draw and constrain the <a href="./geometry.html">geometry</a>.</li><li>Automate with the <a href="./../scripting/console.html">console</a> and the <a href="./../scripting/bridge.html">local bridge</a>.</li></ul>',12)])])}const f=a(s,[["render",i]]);export{p as __pageData,f as default};
